/**
 * 腾讯云 COS 预览服务
 *
 * 将 COS 上的视频文件生成签名临时链接，直接传给 <video> 标签播放，
 * 无需下载到本地，即点即播。
 *
 * 安全方案（STS 临时密钥）：
 *   永久密钥保存在云函数 cloudfunctions/getCosSts 中，
 *   小程序端通过云函数获取临时密钥来初始化 COS SDK，
 *   临时密钥有效期 30 分钟，过期后自动重新获取。
 *
 * 支持两种地址格式：
 *   1. cloud:// 文件 ID — 自动解析为 COS Key，签名后返回可播放链接
 *   2. COS 直链（https://{bucket}.cos.{region}.myqcloud.com/{Key}）— 直接提取 Key 签名
 *
 * 使用示例：
 *   import { getSignedVideoUrl } from '@/utils/cosService.js'
 *   const playUrl = await getSignedVideoUrl('https://cloud2-xxx.cos.ap-shanghai.myqcloud.com/LetteroftheDay/mp4/A.mp4')
 *   videoUrl.value = playUrl
 */

import CosCloud from 'cos-wx-sdk-v5'
import {
  COS_BUCKET,
  COS_REGION,
  COS_URL_EXPIRES,
  COS_STS_FUNCTION,
} from './cosConfig.js'

let cosInstance = null
let stsCache = null // 缓存临时密钥

/**
 * 通过云函数获取 COS 临时密钥（STS）
 */
function fetchSTS() {
  return new Promise((resolve, reject) => {
    wx.cloud.callFunction({
      name: COS_STS_FUNCTION,
      success: (res) => {
        if (res.result && res.result.code === 0) {
          resolve(res.result.data)
        } else {
          reject(new Error(res.result?.message || '获取临时密钥失败'))
        }
      },
      fail: (err) => {
        console.error('[COS STS] 云函数调用失败:', err)
        reject(err)
      },
    })
  })
}

/**
 * 获取有效的临时密钥，如果缓存已过期则重新获取
 */
async function getValidSTS() {
  const now = Math.floor(Date.now() / 1000)
  // 提前 5 分钟刷新，避免过期
  if (stsCache && stsCache.expiredTime - now > 300) {
    return stsCache
  }
  const data = await fetchSTS()
  stsCache = data
  console.log('[COS STS] 获取临时密钥成功，有效期至:', data.expiredTime)
  return data
}

/**
 * 获取 COS SDK 实例（使用临时密钥，自动刷新）
 */
async function getCOSInstance() {
  if (cosInstance) {
    // 检查是否快过期，快过期则重新创建实例
    const now = Math.floor(Date.now() / 1000)
    if (stsCache && stsCache.expiredTime - now > 300) {
      return cosInstance
    }
  }

  const sts = await getValidSTS()
  cosInstance = new CosCloud({
    SecretId: sts.tmpSecretId,
    SecretKey: sts.tmpSecretKey,
    SessionToken: sts.sessionToken,
  })
  return cosInstance
}

/**
 * 将 COS 域名直链转换为对象键（Key）
 *
 * 输入示例：
 *   'https://cloud2-1258683316.cos.ap-shanghai.myqcloud.com/LetteroftheDay/mp4/A.mp4'
 *   转换为：'LetteroftheDay/mp4/A.mp4'
 *
 * 如果不是 COS 域名格式，返回原字符串
 */
function parseCOSKey(url) {
  const cosUrlMatch = url.match(
    /^https?:\/\/[^/]+\.cos\.[^/]+\.myqcloud\.com\/(.+)/,
  )
  if (cosUrlMatch) {
    // 解码已编码的中文路径，防止 COS SDK 再次编码导致双重编码（%E5 -> %25E5）
    return decodeURIComponent(cosUrlMatch[1])
  }
  return url
}

/** 判断一个 URL 是否是 COS 域名直链 */
export function isCOSUrl(url) {
  if (!url) return false
  return /^https?:\/\/[^/]+\.cos\.[^/]+\.myqcloud\.com\//.test(url)
}

/**
 * 使用 COS SDK 获取临时下载链接
 * 适用于小文件或需要直接获取链接的场景
 */
async function getCOSObjectUrl(cosKey) {
  const cos = await getCOSInstance()
  return new Promise((resolve, reject) => {
    cos.getObjectUrl(
      {
        Bucket: COS_BUCKET,
        Region: COS_REGION,
        Key: cosKey,
        Sign: true,
        Expires: COS_URL_EXPIRES,
      },
      (err, data) => {
        if (err) {
          console.error('[COS SDK] getObjectUrl 失败:', err)
          reject(err)
          return
        }
        console.log('[COS SDK] getObjectUrl 成功:', data.Url)
        resolve(data.Url)
      },
    )
  })
}

/**
 * 获取 COS 视频的签名播放链接
 * 直接返回签名后的临时 URL，无需下载，<video> 标签可直接播放
 *
 * @param {string} fileUrl - cloud:// 文件ID 或 COS 直链
 * @returns {Promise<string>} - 签名后的可播放 URL
 */
export async function getSignedVideoUrl(fileUrl) {
  try {
    const cosKey = parseCOSKey(fileUrl)
    console.log('[COS SDK] 解析 Key:', cosKey)

    const signedUrl = await getCOSObjectUrl(cosKey)
    console.log('[COS SDK] 签名播放链接:', signedUrl)

    return signedUrl
  } catch (err) {
    console.error('[COS SDK] 签名失败:', err)
    throw err
  }
}

export default {
  getSignedVideoUrl,
}
